import * as T from 'three/tsl';
export function meshDistanceFieldNode(scene,ao){
 const load=T.Fn(([index])=>{const height=ao.w.div(4096).floor(),width=ao.w.sub(height.mul(4096)),w=width.lessThan(.5).select(4096,width);return T.textureLoad(scene,T.ivec2(index.sub(index.div(w).floor().mul(w)),index.div(w).floor()));});
 const box=(p,lo,hi)=>T.max(T.max(lo.sub(p),p.sub(hi)),T.vec3(0)).length();
 const scalarInteger=T.Fn(([base,index])=>{const integer=T.int(index),group=integer.div(T.int(4)),lane=integer.sub(group.mul(T.int(4))),v=load(base.add(3).add(T.float(group)));return lane.equal(0).select(v.x,lane.equal(1).select(v.y,lane.equal(2).select(v.z,v.w)));});
 const distance=T.Fn(([p,maximum])=>{const root=load(T.float(0)).toVar(),node=T.float(0).toVar(),best=maximum.toVar(),error=T.float(0).toVar();
  T.Loop({start:0,end:T.int(root.x),type:'int',condition:'<',name:'dfNode'},()=>{T.If(node.greaterThanEqual(root.x).or(best.lessThanEqual(0)),()=>T.Break());const lo=load(root.y.add(node.mul(3))).toVar(),hi=load(root.y.add(node.mul(3)).add(1)).toVar(),meta=load(root.y.add(node.mul(3)).add(2)).toVar();T.If(box(p,lo.xyz,hi.xyz).greaterThanEqual(best),()=>{node.assign(lo.w);T.Continue();});
   T.Loop({start:0,end:T.int(meta.x),type:'int',name:'dfItem'},({dfItem:item})=>{T.If(best.lessThanEqual(0),()=>T.Break());const at=root.z.add(hi.w.add(T.float(item)).mul(6)),a=load(at).toVar(),b=load(at.add(1)).toVar(),minimum=box(p,a.xyz,b.xyz);T.If(minimum.greaterThanEqual(best),()=>T.Continue());const rx=load(at.add(2)),ry=load(at.add(3)),rz=load(at.add(4)),info=load(at.add(5)),lower=load(a.w),upper=load(a.w.add(1)),dims=load(a.w.add(2)),local=T.vec3(rx.xyz.dot(p).add(rx.w),ry.xyz.dot(p).add(ry.w),rz.xyz.dot(p).add(rz.w)),value=T.float(0).toVar();T.If(dims.w.greaterThan(.5),()=>{const q=local.sub(lower.xyz.add(upper.xyz).mul(.5)).abs().sub(upper.xyz.sub(lower.xyz).mul(.5));value.assign(T.max(q,T.vec3(0)).length().add(T.min(T.max(q.x,T.max(q.y,q.z)),0)));}).Else(()=>{const coord=local.sub(lower.xyz).div(upper.xyz.sub(lower.xyz)).mul(dims.xyz.sub(1)).clamp(T.vec3(0),dims.xyz.sub(1)).toVar(),cell=coord.floor(),f=coord.sub(cell);
    T.Loop({start:0,end:8,type:'int',name:'dfCorner'},({dfCorner:corner})=>{const z=T.float(corner).mul(.25).floor(),y=T.float(corner).sub(z.mul(4)).mul(.5).floor(),x=T.float(corner).sub(z.mul(4)).sub(y.mul(2)),bit=T.vec3(x,y,z),q=T.min(cell.add(bit),dims.xyz.sub(1)),weight=T.mix(T.vec3(1).sub(f),f,bit),index=T.int(q.x).add(T.int(q.y).add(T.int(q.z).mul(T.int(dims.y))).mul(T.int(dims.x)));value.addAssign(scalarInteger(a.w,index).mul(weight.x).mul(weight.y).mul(weight.z));});});const d=T.max(minimum,value.sub(lower.w).mul(b.w));T.If(d.lessThan(best),()=>{best.assign(d);error.assign(info.x);});
   });node.addAssign(1);
  });return T.vec2(best,error);
 });
 const ambient=T.Fn(([p,n])=>{const radius=ao.x,local=distance(p,radius),offset=T.max(ao.y,local.y.mul(2)),origin=p.add(n.mul(offset)),tangent=n.cross(n.z.abs().lessThan(.9).select(T.vec3(0,0,1),T.vec3(0,1,0))).normalize(),bitangent=n.cross(tangent),sum=T.float(0).toVar();
  T.Loop({start:0,end:6,type:'int',name:'dfCone'},({dfCone:cone})=>{const angle=T.float(cone).mul(1.0471975512).add(.31),direction=n.mul(.75).add(tangent.mul(angle.cos()).add(bitangent.mul(angle.sin())).mul(.661437828)).normalize(),t=T.max(offset,radius.div(128)).toVar(),visibility=T.float(1).toVar();T.Loop({start:0,end:48,type:'int',name:'dfMarch'},()=>{T.If(t.greaterThanEqual(radius).or(visibility.lessThan(.005)),()=>T.Break());const d=distance(origin.add(direction.mul(t)),radius),coneRadius=T.max(radius.div(256),t.mul(.32));visibility.assign(T.min(visibility,d.x.div(coneRadius).clamp(0,1)));t.addAssign(T.max(d.x.mul(.75),radius.div(128)));});sum.addAssign(visibility);});return T.float(1).sub(sum.div(6)).mul(ao.z).clamp(0,1);
 });return {distance,ambient,scalarInteger};
}
